for _id in G14 G15 G16 G17 G18 G19 G20 G21 G22 G23 G24 G25 G26; do
  eval "up_$_id() { true; }"
done
port_verify() { # ID : check every proto:port the registry declares for it
  local spec p proto port bad=""
  spec=$(ports_of "$1")
  for p in $spec; do
    proto=${p%%:*}
    port=${p#*:}
    probe up "$proto" "$VHOST" "$port" >/dev/null 2>&1 || bad="$bad $p"
  done
  if [ -n "$bad" ]; then echo "listener missing on:$bad"; return 2; fi
  echo "listening: $spec (port-only emulator: exposure/reach test, protocol not emulated)"
}
for _id in G14 G15 G16 G17 G18 G19 G20 G21 G22 G23 G24 G25 G26; do
  eval "verify_$_id() { port_verify $_id; }"
done

# ── registry helpers ──────────────────────────────────────────────────────────

sev_rank() { case "$1" in C) echo 3 ;; H) echo 2 ;; M) echo 1 ;; *) echo 0 ;; esac; }
sev_name() { case "$1" in C) echo CRIT ;; H) echo HIGH ;; M) echo MED ;; *) echo ctrl ;; esac; }

ports_of() { # ID -> its "proto:port" list
  printf '%s' "$REG" | awk -F'|' -v id="$1" '$1==id{print $5}'
}

in_csv() { case ",$2," in *",$1,"*) return 0 ;; *) return 1 ;; esac; }

selected() { # ID SEV TYPE
  local id="$1" sev="$2" type="$3"
  if [ "$type" = "CONTROL" ]; then
    [ "$WITH_CONTROLS" -eq 1 ] || return 1
  else
    [ "$(sev_rank "$sev")" -ge "$MIN_RANK" ] || return 1
  fi
  if [ -n "$ONLY" ] && ! in_csv "$id" "$ONLY"; then return 1; fi
  if [ -n "$SKIP" ] && in_csv "$id" "$SKIP"; then return 1; fi
  return 0
}

rec() { # ID STATUS DETAIL
  local d
  d=$(printf '%s' "$3" | tr '\n\t' '  ' | cut -c1-170)
  printf '%s\t%s\t%s\n' "$1" "$2" "$d" >>"$RESULTS"
}

result_of() { awk -F'\t' -v id="$1" '$1==id{r=$2"\t"$3} END{print r}' "$RESULTS" 2>/dev/null; }

# ── firewall (installed BEFORE any service starts) ────────────────────────────

collect_ports() { # fills TCP_PORTS / UDP_PORTS from the selected scenarios
  TCP_PORTS=""
  UDP_PORTS=""
  LISTEN_TCP=""
  LISTEN_UDP=""
  local id sev type name ports p
  while IFS='|' read -r id sev type name ports; do
    [ -n "$id" ] || continue
    selected "$id" "$sev" "$type" || continue
    for p in $ports; do
      case "$p" in
        tcp:*) TCP_PORTS="$TCP_PORTS ${p#tcp:}"; [ "$type" = PORTONLY ] && LISTEN_TCP="$LISTEN_TCP,${p#tcp:}" ;;
        udp:*) UDP_PORTS="$UDP_PORTS ${p#udp:}"; [ "$type" = PORTONLY ] && LISTEN_UDP="$LISTEN_UDP,${p#udp:}" ;;
      esac
    done
  done <<EOF
$REG
EOF
  LISTEN_TCP="${LISTEN_TCP#,}"
  LISTEN_UDP="${LISTEN_UDP#,}"
  if [ "${MERGE_PORTS:-0}" -eq 1 ] && [ -r "$CONF_DIR/lab.conf" ]; then
    # A partial re-run (--only / retry-failed) must NOT shrink the firewall or the shared
    # listener: keep every port a previous run already opened.
    TCP_PORTS=$(merge_list " " "$(conf_get TCP_PORTS)" "$TCP_PORTS")
    UDP_PORTS=$(merge_list " " "$(conf_get UDP_PORTS)" "$UDP_PORTS")
    LISTEN_TCP=$(merge_list "," "$(conf_get LISTEN_TCP)" "$LISTEN_TCP")
    LISTEN_UDP=$(merge_list "," "$(conf_get LISTEN_UDP)" "$LISTEN_UDP")
  fi
}

conf_get() { sed -n "s/^$1=\"\\(.*\\)\"\$/\\1/p" "$CONF_DIR/lab.conf" 2>/dev/null | tail -n 1; }

merge_list() { # separator list... -> de-duplicated list joined by separator
  local sep="$1"
  shift
  printf '%s\n' "$@" | tr ' ,' '\n\n' | grep -v '^$' | sort -u | tr '\n' "$sep" | sed "s/[$sep]\$//"
}

write_lab_conf() {
  cat >"$CONF_DIR/lab.conf" <<EOF
ALLOW_CIDR="$ALLOW_CIDR"
TCP_PORTS="$TCP_PORTS"
UDP_PORTS="$UDP_PORTS"
LISTEN_TCP="$LISTEN_TCP"
LISTEN_UDP="$LISTEN_UDP"
EOF
}

fw_apply() {
  [ -r "$CONF_DIR/lab.conf" ] || die "no $CONF_DIR/lab.conf"
  # shellcheck disable=SC1091
  . "$CONF_DIR/lab.conf"
  local p c
  for c in iptables ip6tables; do
    command -v "$c" >/dev/null 2>&1 || continue
    "$c" -N "$CHAIN" 2>/dev/null || "$c" -F "$CHAIN"
    "$c" -C INPUT -j "$CHAIN" 2>/dev/null || "$c" -I INPUT 1 -j "$CHAIN"
    if [ "$c" = iptables ]; then
      for p in $(cat "$CONF_DIR/blind.tcp" 2>/dev/null); do "$c" -A "$CHAIN" ! -i lo -p tcp --dport "$p" -j DROP; done
      for p in $(cat "$CONF_DIR/blind.udp" 2>/dev/null); do "$c" -A "$CHAIN" ! -i lo -p udp --dport "$p" -j DROP; done
    fi
    "$c" -A "$CHAIN" -i lo -j RETURN
    [ "$c" = iptables ] && "$c" -A "$CHAIN" -s "$ALLOW_CIDR" -j RETURN
    for p in $TCP_PORTS; do "$c" -A "$CHAIN" -p tcp --dport "$p" -j DROP; done
    for p in $UDP_PORTS; do "$c" -A "$CHAIN" -p udp --dport "$p" -j DROP; done
  done
}

fw_remove() {
  local c
  for c in iptables ip6tables; do
    command -v "$c" >/dev/null 2>&1 || continue
    while "$c" -D INPUT -j "$CHAIN" 2>/dev/null; do :; done
    "$c" -F "$CHAIN" 2>/dev/null
    "$c" -X "$CHAIN" 2>/dev/null
  done
}

install_firewall() {
  pkg iptables
  write_lab_conf
  cat >/etc/systemd/system/vedha-lab-firewall.service <<EOF
[Unit]
Description=Vedha lab firewall (lab ports reachable only from the allowed CIDR)
DefaultDependencies=no
Before=network-pre.target
Wants=network-pre.target

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=$LAB_DIR/lab.sh fw-apply

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable vedha-lab-firewall.service >/dev/null 2>&1
  fw_apply
  iptables -S "$CHAIN" >/dev/null 2>&1 || { echo "lab firewall chain was not created"; return 1; }
}

# ── engine ────────────────────────────────────────────────────────────────────

run_one() { # ID SEV TYPE NAME
  local id="$1" log="$LOG_DIR/$1.log" out rc
  : >"$log"
  ( set -e; "up_$id" ) >>"$log" 2>&1
  rc=$?
  if [ $rc -ne 0 ]; then
    rec "$id" FAILED "setup failed (rc=$rc): $(grep -v '^$' "$log" | tail -n 1) [log: $log]"
    return
  fi
  out=$("verify_$id" 2>&1)
  rc=$?
  case $rc in
    0) rec "$id" VERIFIED "$out" ;;
    3) rec "$id" UNCONFIRMED "$out" ;;
    *) rec "$id" FAILED "$out [log: $log]" ;;
  esac
}

live_echo() { # one human-readable line per scenario, as soon as it finishes
  local r st detail
  r=$(result_of "$1")
  st=${r%%$'\t'*}
  detail=${r#*$'\t'}
  case "$st" in
    VERIFIED)    printf '      -> CREATED and VERIFIED   %s\n' "$detail" ;;
    UNCONFIRMED) printf '      -> CREATED, weakness not independently proven   %s\n' "$detail" ;;
    *)           printf '      -> NOT CREATED / FAILED   %s\n' "$detail" ;;
  esac
}

run_selected() { # mode: build | verify
  local mode="$1" id sev type name ports
  while IFS='|' read -r id sev type name ports; do
    [ -n "$id" ] || continue
    selected "$id" "$sev" "$type" || continue
    printf '  [%s] %s ...\n' "$id" "$name"
    if [ "$mode" = build ]; then
      run_one "$id" "$sev" "$type" "$name"
    else
      local out rc
      out=$("verify_$id" 2>&1)
      rc=$?
      case $rc in 0) rec "$id" VERIFIED "$out" ;; 3) rec "$id" UNCONFIRMED "$out" ;; *) rec "$id" FAILED "$out" ;; esac
    fi
    live_echo "$id"
  done <<EOF
$REG
EOF
}

print_report() {
  local id sev type name ports r st detail nv=0 nu=0 nf=0 shown=0
  {
    echo
    echo "================ VEDHA WEAK LAB REPORT  (script $SCRIPT_VERSION, host $(hostname), $(date '+%Y-%m-%d %H:%M %Z')) ================"
    printf '%-4s %-5s %-9s %-52s %-12s %s\n' ID SEV TYPE SCENARIO RESULT DETAIL
    while IFS='|' read -r id sev type name ports; do
      [ -n "$id" ] || continue
      r=$(result_of "$id")
      [ -n "$r" ] || continue
      st=${r%%$'\t'*}
      detail=${r#*$'\t'}
      shown=$((shown + 1))
      case "$st" in VERIFIED) nv=$((nv + 1)) ;; UNCONFIRMED) nu=$((nu + 1)) ;; *) nf=$((nf + 1)) ;; esac
      printf '%-4s %-5s %-9s %-52s %-12s %s\n' "$id" "$(sev_name "$sev")" "$type" "$(printf '%s' "$name" | cut -c1-52)" "$st" "$detail"
    done <<EOF
$REG
EOF
    echo
    echo "SUMMARY: $shown scenarios/controls -> $nv VERIFIED, $nu UNCONFIRMED (up, weakness not independently proven), $nf FAILED"
    if [ "$nf" -gt 0 ]; then
      echo
      echo "FAILED:"
      # latest status per ID only: earlier FAILED rows of since-fixed scenarios must not show
      awk -F'\t' '{s[$1]=$2; d[$1]=$3} END{for(i in s) if(s[i]=="FAILED") printf "  %s  %s\n", i, d[i]}' "$RESULTS" | sort
    fi
    echo
    echo "NOT HOSTABLE ON THIS UBUNTU HOST (no scenario created):"
    printf '%s\n' "$SKIPPED" | awk -F'|' '{printf "  %-12s %-52s %s\n", $1, $2, $3}'
    echo
    echo "$EXCLUDED_NOTE"
    echo "TYPE: REAL = real product/config; EMULATED = protocol emulator (fingerprint tier, not product-validated);"
    echo "      PORTONLY = listener only (tests reach/exposure); CONTROL = safe twin that must NOT be flagged."
    echo "Sources of truth: logs in $LOG_DIR ; results in $RESULTS"
  } >"$STATE_DIR/last-report.txt"
  cat "$STATE_DIR/last-report.txt"
  [ "$nf" -eq 0 ]
}

# ── commands ──────────────────────────────────────────────────────────────────

parse_flags() {
  ALLOW_CIDR=""; ACK=0; ONLY=""; SKIP=""; MIN_SEV="high"; WITH_CONTROLS=0; PURGE=0
  while [ $# -gt 0 ]; do
    case "$1" in
      --allow-cidr) ALLOW_CIDR="${2:-}"; shift ;;
      --i-understand-isolated-lab) ACK=1 ;;
      --only) ONLY="${2:-}"; shift ;;
      --skip) SKIP="${2:-}"; shift ;;
      --min-severity) MIN_SEV="${2:-}"; shift ;;
      --verify-host) VHOST="${2:-}"; shift ;;
      --no-controls) WITH_CONTROLS=0 ;;
      --with-controls) WITH_CONTROLS=1 ;;
      --purge) PURGE=1 ;;
      *) die "unknown option: $1" ;;
    esac
    shift
  done
  case "$MIN_SEV" in high) MIN_RANK=2 ;; critical) MIN_RANK=3 ;; *) die "--min-severity: high|critical (this edition builds nothing below High)" ;; esac
}

cmd_list() {
  register_all
  parse_flags "$@"
  printf '%-4s %-5s %-9s %-62s %s\n' ID SEV TYPE SCENARIO PORTS
  local id sev type name ports
  while IFS='|' read -r id sev type name ports; do
    [ -n "$id" ] || continue
    selected "$id" "$sev" "$type" || continue
    printf '%-4s %-5s %-9s %-62s %s\n' "$id" "$(sev_name "$sev")" "$type" "$name" "$ports"
  done <<EOF
$REG
EOF
  echo
  echo "NOT HOSTABLE ON UBUNTU:"
  printf '%s\n' "$SKIPPED" | awk -F'|' '{printf "  %-12s %-52s %s\n", $1, $2, $3}'
  echo "$EXCLUDED_NOTE"
}

cmd_up() {
  need_root; check_os; ensure_dirs
  [ -n "$ALLOW_CIDR" ] || die "--allow-cidr is required (the scanner's network, e.g. 192.168.56.0/24)"
  cidr_ok "$ALLOW_CIDR" || die "--allow-cidr must be inside 10/8, 172.16/12, 192.168/16 or 100.64/10"
  [ "$ACK" -eq 1 ] || die "pass --i-understand-isolated-lab: this makes the host deliberately vulnerable"
  local pub
  pub=$(public_iface_ips)
  [ -z "$pub" ] || die "this host has public IPv4 address(es): $pub. Use an isolated lab VM."
  warn "If this VM sits behind NAT / a cloud public IP, also lock the security group. The host firewall below only allows $ALLOW_CIDR."
  register_all
  if [ -n "$ONLY" ]; then touch "$RESULTS"; else : >"$RESULTS"; fi   # partial run keeps earlier results
  MERGE_PORTS=1
  say "== base tools"
  pkg python3 iproute2 curl ca-certificates dnsutils nfs-common ldap-utils snmp rsync openssl openssh-client \
    || warn "some verifier tools failed to install; their checks will report FAILED"
  write_helpers
  install -m 0755 "${BASH_SOURCE[0]}" "$LAB_DIR/lab.sh"
  collect_ports
  say "== firewall first: lab ports reachable only from $ALLOW_CIDR"
  install_firewall || die "could not install the lab firewall; nothing was started"
  VLAN=$(lan_ip)
  if [ -n "$LISTEN_TCP$LISTEN_UDP" ]; then
    say "== shared port-only listener"
    ( set -e; emu listen ${LISTEN_TCP:+--tcp "$LISTEN_TCP"} ${LISTEN_UDP:+--udp "$LISTEN_UDP"} ) >"$LOG_DIR/listen.log" 2>&1 \
      || warn "port-only listener failed to start (see $LOG_DIR/listen.log); G14-G26 will report FAILED"
  fi
  say "== building scenarios"
  run_selected build
  print_report
}

cmd_retry() { # rebuild only what FAILED last time; keeps every other scenario and its firewall rules
  need_root; ensure_dirs
  [ -s "$RESULTS" ] || die "no previous results in $RESULTS; run 'up' first"
  ONLY=$(awk -F'\t' '{r[$1]=$2} END{for(i in r) if(r[i]=="FAILED") printf "%s,", i}' "$RESULTS" | sed 's/,$//')
  if [ -z "$ONLY" ]; then
    say "nothing FAILED in the last run"
    return 0
  fi
  if [ -z "$ALLOW_CIDR" ]; then ALLOW_CIDR=$(conf_get ALLOW_CIDR); fi
  ACK=1                                  # already acknowledged by the original 'up'
  say "retrying only: $ONLY (allowed network: $ALLOW_CIDR)"
  cmd_up
}

cmd_verify() {
  check_os; ensure_dirs; register_all
  [ -r "$CONF_DIR/lab.conf" ] || die "lab not built (no $CONF_DIR/lab.conf); run 'up' first"
  [ -f "$LAB_DIR/lab_probe.py" ] || die "lab not built"
  VLAN=$(lan_ip)
  if [ -n "$ONLY" ]; then touch "$RESULTS"; else : >"$RESULTS"; fi
  say "== re-verifying (no changes made)"
  run_selected verify
  print_report
}

cmd_blind() { # port [tcp|udp]
  need_root
  local port="${1:-}" proto="${2:-both}"
  [ -n "$port" ] || die "usage: blind PORT [tcp|udp]"
  case "$proto" in tcp|both) echo "$port" >>"$CONF_DIR/blind.tcp" ;; esac
  case "$proto" in udp|both) echo "$port" >>"$CONF_DIR/blind.udp" ;; esac
  fw_apply
  say "port $port ($proto) now DROPPED for everything except loopback. Expect the scanner to report no-evidence, never clean."
}

cmd_unblind() {
  need_root
  local port="${1:-}"
  [ -n "$port" ] || die "usage: unblind PORT"
  local f
  for f in blind.tcp blind.udp; do
    [ -f "$CONF_DIR/$f" ] && grep -vx "$port" "$CONF_DIR/$f" >"$CONF_DIR/$f.new" && mv "$CONF_DIR/$f.new" "$CONF_DIR/$f"
  done
  fw_apply
  say "port $port restored"
}

cmd_down() {
  need_root
  say "== stopping lab units"
  local u
  if [ -f "$STATE_DIR/units.txt" ]; then
    for u in $(sort -u "$STATE_DIR/units.txt"); do
      systemctl disable --now "$u" >/dev/null 2>&1
      rm -f "/etc/systemd/system/$u"
    done
  fi
  systemctl disable --now vedha-lab-firewall.service >/dev/null 2>&1
  fw_remove
  rm -f /etc/systemd/system/vedha-lab-firewall.service
  systemctl daemon-reload
  say "== restoring configs"
  if [ -d "$STATE_DIR/backup" ]; then
    local f rel
    find "$STATE_DIR/backup" -type f | while read -r f; do
      rel=${f#"$STATE_DIR/backup"}
      case "$rel" in
        *.absent) rm -f "${rel%.absent}" ;;
        *) mkdir -p "$(dirname "$rel")"; cp -a "$f" "$rel" ;;
      esac
    done
  fi
  rm -f /etc/exports.d/vedha-lab.exports /etc/nfs.conf.d/vedha-lab.conf /etc/mosquitto/conf.d/vedha-lab.conf \
    /etc/mysql/mariadb.conf.d/99-vedha-lab.cnf /etc/tinyproxy/lab-filter
  a2disconf vedha-lab >/dev/null 2>&1
  rm -f /etc/apache2/conf-available/vedha-lab.conf
  for u in /srv/lab/web/dav /srv/lab/ftp/upload; do mountpoint -q "$u" && umount "$u"; done
  sed -i '/# vedha-lab$/d' /etc/fstab
  if [ -f "$STATE_DIR/touched-svcs.txt" ]; then
    for u in $(sort -u "$STATE_DIR/touched-svcs.txt"); do
      case "$u" in vedha-lab-*) ;; *) systemctl restart "$u" >/dev/null 2>&1 ;; esac
    done
  fi
  if [ "$PURGE" -eq 1 ] && [ -f "$STATE_DIR/new-pkgs.txt" ]; then
    say "== purging packages this script installed"
    # shellcheck disable=SC2046
    DEBIAN_FRONTEND=noninteractive apt-get purge -y -qq $(sort -u "$STATE_DIR/new-pkgs.txt") || warn "purge reported errors"
  else
    say "packages were kept (use 'down --purge' to remove the ones this script added)"
  fi
  rm -rf "$CONF_DIR" "$LAB_DIR" /srv/lab
  say "lab removed. State/logs kept in $STATE_DIR"
}

# Engine self-test with fake scenarios: proves the report logic without touching the host.
cmd_engine_selftest() {
  STATE_DIR="$(mktemp -d)"; LOG_DIR="$STATE_DIR/logs"; RESULTS="$STATE_DIR/results.tsv"
  mkdir -p "$LOG_DIR"; : >"$RESULTS"
  WITH_CONTROLS=1; MIN_RANK=1; ONLY=""; SKIP=""
  REG=""
  reg F01 C REAL     "passes setup and verification"      "tcp:1"
  reg F02 H EMULATED "setup command fails"                "tcp:2"
  reg F03 M REAL     "up but weakness not proven"         "tcp:3"
  reg F04 H REAL     "setup ok, verification says absent" "tcp:4"
  reg F05 M PORTONLY "unreachable after setup"            "tcp:5"
  reg F06 -  CONTROL "control stays clean"                "tcp:6"
  up_F01() { true; };            verify_F01() { echo "weakness confirmed"; return 0; }
  up_F02() { echo "boom"; false; };   verify_F02() { return 0; }
  up_F03() { true; };            verify_F03() { echo "service up"; return 3; }
  up_F04() { true; };            verify_F04() { echo "service is up but NOT weak"; return 1; }
  up_F05() { true; };            verify_F05() { echo "unreachable"; return 2; }
  up_F06() { true; };            verify_F06() { echo "control is clean"; return 0; }
  SKIPPED="X01|example skipped scenario|reason shown here"
  run_selected build
  print_report
  local rc=$?
  local want="F01 VERIFIED|F02 FAILED|F03 UNCONFIRMED|F04 FAILED|F05 FAILED|F06 VERIFIED" got=""
  local i
  for i in F01 F02 F03 F04 F05 F06; do got="${got:+$got|}$i $(result_of "$i" | cut -f1)"; done
  if [ "$got" = "$want" ] && [ "$rc" -ne 0 ]; then
    say "ENGINE SELFTEST: PASS (statuses as expected; exit code non-zero because of FAILED rows)"
    return 0
  fi
  say "ENGINE SELFTEST: FAIL  got=[$got]"
  return 1
}

write_helpers() { # the two helper programs, embedded so this file is self-contained
  cat >"$LAB_DIR/lab_emulators.py" <<'VEDHA_EMU_PY'
#!/usr/bin/env python3
"""Vedha weak-lab emulators.

DELIBERATELY WEAK. These answer just enough of a protocol for the probe scanners to
see the weakness. They exist because the real services cannot be installed natively
on Ubuntu (a camera, a phone, an IPMI BMC, a UPnP router ...). A detection from an
emulator is "fingerprint tier", not product-validated: label it that way.

Safety: no emulator proxies, stores, executes or forwards anything. UDP replies are
rate-limited per source, and the port-only UDP listener answers with 1 byte (no
amplification). Run only on an isolated lab VM behind the lab firewall chain.

    lab_emulators.py serve NAME [--bind ADDR] [--tcp 1,2] [--udp 3,4]
"""
import argparse
import asyncio
import json
import os
import socket
import struct
import sys
import time

RATE_LIMIT_PER_SEC = 20
ROOTDESC_PORT = int(os.environ.get("VEDHA_LAB_ROOTDESC_PORT", "5000"))


def local_ip_for(peer: str) -> str:
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect((peer, 9))
        return s.getsockname()[0]
    except OSError:
        return "127.0.0.1"
    finally:
        s.close()


# ── tiny HTTP helpers ─────────────────────────────────────────────────────────

async def read_head(reader, timeout=5.0) -> bytes:
    try:
        return await asyncio.wait_for(reader.readuntil(b"\r\n\r\n"), timeout)
    except (asyncio.TimeoutError, asyncio.IncompleteReadError,
            asyncio.LimitOverrunError, ConnectionError, OSError):
        return b""


async def http_send(writer, status: str, body: bytes, ctype="text/html", server="lab"):
    head = (f"HTTP/1.1 {status}\r\nServer: {server}\r\nContent-Type: {ctype}\r\n"
            f"Content-Length: {len(body)}\r\nConnection: close\r\n\r\n").encode()
    writer.write(head + body)
    try:
        await writer.drain()
    except OSError:
        pass


def request_path(head: bytes) -> str:
    parts = head.split(b"\r\n", 1)[0].split(b" ")
    return parts[1].decode("latin-1") if len(parts) > 1 else "/"


async def _close(writer):
    try:
        writer.close()
        await writer.wait_closed()
    except OSError:
        pass


# ── TCP services ──────────────────────────────────────────────────────────────

async def rtsp(reader, writer):
    """IP-camera style RTSP: OPTIONS lists methods, DESCRIBE answers without auth."""
    head = await read_head(reader)
    if head:
        lines = head.decode("latin-1").split("\r\n")
        method = lines[0].split(" ")[0]
        cseq = next((ln.split(":", 1)[1].strip() for ln in lines
                     if ln.lower().startswith("cseq:")), "1")
        body = b""
        extra = ""
        status = "200 OK"
        if method == "OPTIONS":
            extra = "Public: OPTIONS, DESCRIBE, SETUP, PLAY, TEARDOWN\r\n"
        elif method == "DESCRIBE":
            body = (b"v=0\r\no=- 0 0 IN IP4 0.0.0.0\r\ns=Lab camera (no auth)\r\n"
                    b"t=0 0\r\nm=video 0 RTP/AVP 96\r\n")
            extra = f"Content-Type: application/sdp\r\nContent-Length: {len(body)}\r\n"
        else:
            status = "405 Method Not Allowed"
        writer.write((f"RTSP/1.0 {status}\r\nCSeq: {cseq}\r\nServer: LabCam/1.0\r\n"
                      f"{extra}\r\n").encode() + body)
        try:
            await writer.drain()
        except OSError:
            pass
    await _close(writer)


async def cwmp(reader, writer):
    """TR-069 / CWMP connection-request listener on 7547."""
    await read_head(reader)
    await http_send(writer, "200 OK",
                    b"<html><body>CWMP ACS connection-request endpoint</body></html>",
                    server="gSOAP/2.8")
    await _close(writer)


A_CNXN = 0x4E584E43


async def adb(reader, writer):
    """Android Debug Bridge over TCP, no AUTH step: answers CNXN with CNXN."""
    try:
        hdr = await asyncio.wait_for(reader.readexactly(24), 5)
        cmd, _a0, _a1, dlen, _crc, _magic = struct.unpack("<IIIIII", hdr)
        if dlen:
            await asyncio.wait_for(reader.readexactly(min(dlen, 65536)), 5)
        if cmd == A_CNXN:
            payload = (b"device::ro.product.name=labdevice;ro.product.model=LabPhone;"
                       b"ro.product.device=lab;features=shell_v2,cmd\x00")
            out = struct.pack("<IIIIII", A_CNXN, 0x01000000, 256 * 1024, len(payload),
                              sum(payload) & 0xFFFFFFFF, A_CNXN ^ 0xFFFFFFFF)
            writer.write(out + payload)
            await writer.drain()
    except (asyncio.TimeoutError, asyncio.IncompleteReadError, OSError):
        pass
    await _close(writer)


async def ollama(reader, writer):
    """Ollama-shaped API with no authentication."""
    head = await read_head(reader)
    path = request_path(head).split("?")[0]
    if path == "/":
        await http_send(writer, "200 OK", b"Ollama is running", "text/plain")
    elif path == "/api/tags":
        body = json.dumps({"models": [{"name": "llama3:8b", "model": "llama3:8b",
                                       "size": 4661224676}]}).encode()
        await http_send(writer, "200 OK", body, "application/json")
    elif path == "/api/version":
        await http_send(writer, "200 OK", json.dumps({"version": "0.3.12"}).encode(),
                        "application/json")
    else:
        await http_send(writer, "404 Not Found", b"404 page not found", "text/plain")
    await _close(writer)


ROOTDESC = b"""<?xml version="1.0"?>
<root xmlns="urn:schemas-upnp-org:device-1-0"><specVersion><major>1</major><minor>0</minor></specVersion>
<device><deviceType>urn:schemas-upnp-org:device:InternetGatewayDevice:1</deviceType>
<friendlyName>Lab Router</friendlyName><manufacturer>LabCorp</manufacturer><modelName>LabIGD</modelName>
<deviceList><device><deviceType>urn:schemas-upnp-org:device:WANDevice:1</deviceType>
<deviceList><device><deviceType>urn:schemas-upnp-org:device:WANConnectionDevice:1</deviceType>
<serviceList><service><serviceType>urn:schemas-upnp-org:service:WANIPConnection:1</serviceType>
<controlURL>/ctl/IPConn</controlURL></service></serviceList></device></deviceList></device></deviceList>
</device></root>"""


async def rootdesc(reader, writer):
    head = await read_head(reader)
    if request_path(head).split("?")[0] == "/rootDesc.xml":
        await http_send(writer, "200 OK", ROOTDESC, "text/xml", "MiniUPnPd/2.1")
    else:
        await http_send(writer, "404 Not Found", b"not found", "text/plain")
    await _close(writer)


def sip_reply(req: bytes) -> bytes:
    text = req.decode("latin-1", "replace")
    first = text.split("\r\n", 1)[0]
    hdrs: dict = {}
    for line in text.split("\r\n")[1:]:
        if ":" in line:
            k, _, v = line.partition(":")
            hdrs.setdefault(k.strip().lower(), []).append(v.strip())

    def g(k):
        return hdrs.get(k, [""])[0]

    status = "200 OK" if first.startswith("OPTIONS") else "405 Method Not Allowed"
    lines = [f"SIP/2.0 {status}"]
    lines += ["Via: " + v for v in hdrs.get("via", [])]
    lines += ["From: " + g("from"), "To: " + g("to") + ";tag=lab1",
              "Call-ID: " + g("call-id"), "CSeq: " + g("cseq"),
              "Allow: INVITE, ACK, CANCEL, OPTIONS, BYE, REGISTER",
              "Server: Asterisk PBX 16.2.1", "Content-Length: 0", "", ""]
    return "\r\n".join(lines).encode()


async def sip_tcp(reader, writer):
    head = await read_head(reader)
    if head:
        writer.write(sip_reply(head))
        try:
            await writer.drain()
        except OSError:
            pass
    await _close(writer)


async def hold(reader, writer):
    """Port-only listener: accept, say nothing, drop after a second."""
    try:
        await asyncio.wait_for(reader.read(64), 1.0)
    except (asyncio.TimeoutError, OSError):
        pass
    await _close(writer)


# ── UDP services: handler(data, addr) -> list[bytes] ──────────────────────────

def udp_ssdp(data, addr):
    if b"M-SEARCH" not in data:
        return []
    loc = f"http://{local_ip_for(addr[0])}:{ROOTDESC_PORT}/rootDesc.xml"
    return [("HTTP/1.1 200 OK\r\nCACHE-CONTROL: max-age=1800\r\n"
             f"LOCATION: {loc}\r\nSERVER: Linux/5.15 UPnP/1.1 MiniUPnPd/2.1\r\n"
             "ST: upnp:rootdevice\r\nUSN: uuid:lab-igd::upnp:rootdevice\r\n\r\n").encode()]


def udp_ntp(data, addr):
    """Mode 3 -> normal server reply. Mode 7 MON_GETLIST(_1) -> a large monlist."""
    if not data:
        return []
    mode = data[0] & 7
    if mode == 3:
        return [b"\x1c\x02\x00\xec" + b"\x00" * 44]
    if mode == 7 and len(data) >= 4 and data[3] in (20, 42):
        n = 6
        out = []
        for i in range(n):
            b0 = 0x97 | (0x40 if i < n - 1 else 0)      # R=1, M=more, VN=2, mode 7
            hdr = bytes([b0, i, 3, data[3]]) + struct.pack(">HH", 6, 72)
            out.append(hdr + b"\x00" * (6 * 72))
        return out
    return []


def udp_sip(data, addr):
    return [sip_reply(data)] if data.startswith(b"OPTIONS") else []


def udp_ipmi(data, addr):
    """ASF presence ping -> pong; RMCP+ Open Session with cipher 0 -> status 0 (accepted)."""
    if len(data) >= 12 and data[0] == 0x06 and data[3] == 0x06:     # ASF class
        return [bytes([6, 0, 0xFF, 6, 0, 0, 0x11, 0xBE, 0x40, data[9], 0, 0x10,
                       0, 0, 0x11, 0xBE, 0, 0, 0, 0, 0x81, 0, 0, 0, 0, 0, 0, 0])]
    if len(data) >= 24 and data[0] == 0x06 and data[3] == 0x07 and data[5] == 0x10:
        tag, console_sid = data[16], data[20:24]
        payload = (bytes([tag, 0x00, 0x04, 0x00]) + console_sid + b"\x01\x02\x03\x04"
                   + bytes([0, 0, 0, 8, 0, 0, 0, 0])
                   + bytes([1, 0, 0, 8, 0, 0, 0, 0])
                   + bytes([2, 0, 0, 8, 0, 0, 0, 0]))
        return [bytes([6, 0, 0xFF, 7, 6, 0x11]) + b"\x00" * 8
                + struct.pack("<H", len(payload)) + payload]
    return []


def udp_echo1(data, addr):
    return [b"\x00"]


class UdpProto(asyncio.DatagramProtocol):
    def __init__(self, handler):
        self.handler = handler
        self.hits: dict = {}
        self.transport = None

    def connection_made(self, transport):
        self.transport = transport

    def datagram_received(self, data, addr):
        now = int(time.time())
        sec, count = self.hits.get(addr[0], (now, 0))
        count = count + 1 if sec == now else 1
        self.hits[addr[0]] = (now, count)
        if count > RATE_LIMIT_PER_SEC:
            return
        try:
            for pkt in self.handler(data, addr):
                self.transport.sendto(pkt, addr)
        except Exception as exc:                                  # never crash the lab
            print(f"udp handler error: {exc}", file=sys.stderr)


# name -> (tcp ports, udp ports, tcp handler, udp handler, extra tcp {port: handler})
SERVICES = {
    "rtsp":   ([554, 8554], [], rtsp, None, {}),
    "cwmp":   ([7547], [], cwmp, None, {}),
    "adb":    ([5555], [], adb, None, {}),
    "ollama": ([11434], [], ollama, None, {}),
    "ssdp":   ([], [1900], None, udp_ssdp, {ROOTDESC_PORT: rootdesc}),
    "ntp":    ([], [123], None, udp_ntp, {}),
    "sip":    ([5060], [5060], sip_tcp, udp_sip, {}),
    "ipmi":   ([], [623], None, udp_ipmi, {}),
    "listen": ([], [], hold, udp_echo1, {}),
}


async def run(name, bind, tcp_ports, udp_ports):
    _tcp, _udp, tcp_h, udp_h, extra = SERVICES[name]
    loop = asyncio.get_running_loop()
    started = []
    for p in tcp_ports:
        await asyncio.start_server(tcp_h, bind, p)
        started.append(f"tcp/{p}")
    for p, h in extra.items():
        await asyncio.start_server(h, bind, p)
        started.append(f"tcp/{p}")
    for p in udp_ports:
        await loop.create_datagram_endpoint(lambda: UdpProto(udp_h), local_addr=(bind, p))
        started.append(f"udp/{p}")
    print(f"vedha-lab emulator '{name}' listening on {bind}: {', '.join(started)}", flush=True)
    await asyncio.Event().wait()


def parse_ports(text):
    return [int(x) for x in text.split(",") if x.strip()] if text else None


def main():
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    sub = ap.add_subparsers(dest="cmd", required=True)
    sv = sub.add_parser("serve")
    sv.add_argument("name", choices=sorted(SERVICES))
    sv.add_argument("--bind", default="0.0.0.0")
    sv.add_argument("--tcp", default=None, help="comma list; overrides the default")
    sv.add_argument("--udp", default=None, help="comma list; overrides the default")
    a = ap.parse_args()
    d_tcp, d_udp = SERVICES[a.name][0], SERVICES[a.name][1]
    tcp = parse_ports(a.tcp) if a.tcp is not None else d_tcp
    udp = parse_ports(a.udp) if a.udp is not None else d_udp
    if a.name == "listen" and not (tcp or udp):
        ap.error("'listen' needs --tcp and/or --udp")
    try:
        asyncio.run(run(a.name, a.bind, tcp, udp))
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()
VEDHA_EMU_PY
  cat >"$LAB_DIR/lab_probe.py" <<'VEDHA_PROBE_PY'
#!/usr/bin/env python3
"""Independent verifier for the Vedha weak lab.

Deliberately does NOT use the Vedha probe scanners: the point is to prove the weakness
exists *before* Vedha is pointed at it, so a pass here is not circular.

    lab_probe.py up tcp|udp HOST PORT
    lab_probe.py check NAME HOST [PORT]

Exit codes:  0 weakness CONFIRMED   1 service reachable, weakness ABSENT
             2 service UNREACHABLE or a required tool is missing
The single line on stdout is the human-readable evidence / reason.
"""
import http.client
import io
import os
import re
import shutil
import socket
import struct
import subprocess
import sys
import urllib.request

CONF_DIR = os.environ.get("VEDHA_LAB_CONF_DIR", "/etc/vedha-lab")
CONFIRMED, ABSENT, UNREACHABLE = 0, 1, 2


class Unreachable(Exception):
    pass


def tcp(host, port, timeout=6.0):
    try:
        s = socket.create_connection((host, port), timeout)
        s.settimeout(timeout)
        return s
    except OSError as exc:
        raise Unreachable(f"{host}:{port}/tcp {exc}")


def recv_n(s, n):
    buf = b""
    while len(buf) < n:
        chunk = s.recv(n - len(buf))
        if not chunk:
            raise Unreachable("connection closed early")
        buf += chunk
    return buf


def udp_exchange(host, port, payload, timeout=4.0, extra_wait=0.0):
    """Send one datagram, return the list of reply datagrams."""
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.settimeout(timeout)
    out = []
    try:
        s.sendto(payload, (host, port))
        out.append(s.recvfrom(65535)[0])
        if extra_wait:
            s.settimeout(extra_wait)
            while True:
                out.append(s.recvfrom(65535)[0])
    except socket.timeout:
        pass
    except OSError as exc:
        raise Unreachable(f"{host}:{port}/udp {exc}")
    finally:
        s.close()
    if not out:
        raise Unreachable(f"{host}:{port}/udp no reply")
    return out


def need(tool):
    if not shutil.which(tool):
        raise Unreachable(f"verifier tool '{tool}' is not installed")


def run(cmd, timeout=20):
    need(cmd[0])
    p = subprocess.run(cmd, capture_output=True, timeout=timeout)
    return (p.stdout + p.stderr).decode("utf-8", "replace")


# ── SSH ───────────────────────────────────────────────────────────────────────

def ssh_kexinit(host, port):
    s = tcp(host, port)
    banner = b""
    while not banner.endswith(b"\n") and len(banner) < 512:
        c = s.recv(1)
        if not c:
            break
        banner += c
    s.sendall(b"SSH-2.0-LabProbe_1.0\r\n")
    plen = struct.unpack(">I", recv_n(s, 4))[0]
    body = recv_n(s, plen)
    payload = body[1:plen - body[0]]
    if not payload or payload[0] != 20:
        raise Unreachable("no SSH_MSG_KEXINIT")
    off, lists = 17, []
    for _ in range(10):
        ln = struct.unpack(">I", payload[off:off + 4])[0]
        off += 4
        lists.append(payload[off:off + ln].decode().split(",") if ln else [])
        off += ln
    s.close()
    return banner.decode("latin-1").strip(), lists


WEAK_KEX = {"diffie-hellman-group1-sha1", "diffie-hellman-group14-sha1",
            "diffie-hellman-group-exchange-sha1"}


def c_ssh_weak(host, port):
    banner, lists = ssh_kexinit(host, port)
    kex, ciphers = lists[0], lists[2]
    wk = sorted(WEAK_KEX & set(kex))
    wc = [c for c in ciphers if any(t in c for t in ("cbc", "arcfour", "3des"))]
    if wk or wc:
        return CONFIRMED, f"{banner}: weak kex={wk} weak ciphers={wc}"
    return ABSENT, f"{banner}: no SHA-1 kex or CBC/3DES/RC4 cipher offered"


def c_ssh_terrapin(host, port):
    banner, lists = ssh_kexinit(host, port)
    kex, ciphers = lists[0], lists[2]
    strict = "kex-strict-s-v00@openssh.com" in kex
    risky = [c for c in ciphers if "chacha20" in c or "cbc" in c]
    if not strict and risky:
        return CONFIRMED, f"{banner}: no strict-kex marker, offers {risky[:2]}"
    return ABSENT, f"{banner}: strict-kex={strict} risky ciphers={bool(risky)}"


# ── VNC ───────────────────────────────────────────────────────────────────────

def vnc_types(host, port):
    s = tcp(host, port)
    ver = recv_n(s, 12)
    if not ver.startswith(b"RFB"):
        raise Unreachable(f"not VNC: {ver!r}")
    s.sendall(b"RFB 003.008\n")
    n = recv_n(s, 1)[0]
    if n == 0:
        raise Unreachable("VNC server refused the handshake")
    types = list(recv_n(s, n))
    s.close()
    return ver.decode().strip(), types


def c_vnc_none(host, port):
    ver, types = vnc_types(host, port)
    return (CONFIRMED if 1 in types else ABSENT), f"{ver} security types {types}"


def c_vnc_auth(host, port):
    ver, types = vnc_types(host, port)
    return (CONFIRMED if 2 in types and 1 not in types else ABSENT), f"{ver} security types {types}"


# ── IPMI (cipher zero) ────────────────────────────────────────────────────────

def c_ipmi_cipher0(host, port):
    payload = (bytes([0, 0, 0, 0]) + b"\xa0\xa1\xa2\xa3"
               + bytes([0, 0, 0, 8, 0, 0, 0, 0]) + bytes([1, 0, 0, 8, 0, 0, 0, 0])
               + bytes([2, 0, 0, 8, 0, 0, 0, 0]))
    req = (bytes([0x06, 0x00, 0xFF, 0x07]) + bytes([0x06, 0x10]) + b"\x00" * 8
           + struct.pack("<H", len(payload)) + payload)
    resp = udp_exchange(host, port, req)[0]
    if len(resp) < 18 or resp[0] != 0x06 or resp[5] != 0x11:
        return ABSENT, f"reply is not an RMCP+ Open Session Response: {resp[:8].hex()}"
    status = resp[17]
    return (CONFIRMED if status == 0 else ABSENT), f"RMCP+ open-session status 0x{status:02x}"


# ── datastores, mail, ftp, tftp ───────────────────────────────────────────────

def c_redis_noauth(host, port):
    s = tcp(host, port)
    s.sendall(b"PING\r\n")
    r = s.recv(64)
    s.close()
    if r.startswith(b"+PONG"):
        return CONFIRMED, "PING answered without authentication"
    return ABSENT, f"reply {r[:40]!r}"


def c_mqtt_anon(host, port):
    cid = b"mqtt-client"
    rem = b"\x00\x04MQTT" + b"\x04\x02" + struct.pack(">H", 60) + struct.pack(">H", len(cid)) + cid
    s = tcp(host, port)
    s.sendall(b"\x10" + bytes([len(rem)]) + rem)
    r = s.recv(16)
    s.close()
    if len(r) >= 4 and r[0] == 0x20:
        return (CONFIRMED if r[3] == 0 else ABSENT), f"CONNACK return code {r[3]}"
    return ABSENT, f"no CONNACK: {r!r}"


def c_mysql_cleartext(host, port):
    s = tcp(host, port)
    pkt = s.recv(512)
    s.close()
    if len(pkt) < 20 or pkt[4] != 10:
        raise Unreachable(f"not a MySQL greeting: {pkt[:12]!r}")
    end = pkt.index(b"\x00", 5)
    version = pkt[5:end].decode("latin-1")
    caps = struct.unpack("<H", pkt[end + 14:end + 16])[0]
    if caps & 0x0800:
        return ABSENT, f"{version}: server offers TLS (CLIENT_SSL set)"
    return CONFIRMED, f"{version}: server does not offer TLS"


def c_tftp_read(host, port):
    r = udp_exchange(host, port, b"\x00\x01lab.txt\x00octet\x00")[0]
    op = struct.unpack(">H", r[:2])[0]
    if op == 3:
        return CONFIRMED, f"RRQ lab.txt answered with DATA ({len(r) - 4} bytes)"
    return ABSENT, f"opcode {op}: {r[4:60]!r}"


def c_ftp_anon_write(host, port):
    import ftplib
    ftp = ftplib.FTP()
    try:
        ftp.connect(host, port, timeout=8)
    except OSError as exc:
        raise Unreachable(str(exc))
    try:
        ftp.login()
        ftp.cwd("upload")
        ftp.storbinary("STOR vedha-probe.txt", io.BytesIO(b"probe"))
        ftp.delete("vedha-probe.txt")
        return CONFIRMED, "anonymous login can STOR into /upload"
    except ftplib.all_errors as exc:
        return ABSENT, f"anonymous write refused: {exc}"
    finally:
        try:
            ftp.close()
        except OSError:
            pass


def c_smtp_relay(host, port):
    import smtplib
    s = smtplib.SMTP(timeout=8)
    try:
        s.connect(host, port)
        s.ehlo()
        starttls = s.has_extn("starttls")
        s.mail("<probe@external.invalid>")
        code, _ = s.rcpt("<victim@external.invalid>")
        vcode, _ = s.verify("root")
        s.rset()
    except OSError as exc:
        raise Unreachable(str(exc))
    except smtplib.SMTPException as exc:
        return ABSENT, f"SMTP refused: {exc}"
    finally:
        try:
            s.close()
        except OSError:
            pass
    detail = f"RCPT external={code} VRFY={vcode} STARTTLS={'yes' if starttls else 'no'} (no DATA sent)"
    return (CONFIRMED if code in (250, 251) else ABSENT), detail


# ── web / TLS ─────────────────────────────────────────────────────────────────

def c_http_methods(host, port):
    try:
        c = http.client.HTTPConnection(host, port, timeout=8)
        c.request("OPTIONS", "/dav/")
        r = c.getresponse()
        allow = r.getheader("Allow", "")
        r.read()
        c.request("TRACE", "/")
        t = c.getresponse()
        t.read()
    except OSError as exc:
        raise Unreachable(str(exc))
    bad = [m for m in ("PUT", "DELETE") if m in allow]
    if bad or t.status == 200:
        return CONFIRMED, f"Allow='{allow}' TRACE={t.status}"
    return ABSENT, f"Allow='{allow}' TRACE={t.status}"


def tls_cert(host, port):
    need("openssl")
    env = dict(os.environ)
    conf = os.path.join(CONF_DIR, "openssl-seclevel0.cnf")
    if os.path.exists(conf):
        env["OPENSSL_CONF"] = conf
    p = subprocess.run(["openssl", "s_client", "-connect", f"{host}:{port}", "-showcerts",
                        "-cipher", "DEFAULT:@SECLEVEL=0"], input=b"", capture_output=True,
                       timeout=20, env=env)
    pem = re.search(r"-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----",
                    p.stdout.decode("latin-1"), re.S)
    if not pem:
        raise Unreachable(f"{host}:{port} no certificate returned")
    t = subprocess.run(["openssl", "x509", "-noout", "-text"], input=pem.group(0).encode(),
                       capture_output=True, timeout=10, env=env).stdout.decode("latin-1")
    bits = re.search(r"Public-Key: \((\d+) bit\)", t)
    sig = re.search(r"Signature Algorithm: (\S+)", t)
    return (int(bits.group(1)) if bits else 0), (sig.group(1) if sig else "?")


def c_tls_weakkey(host, port):
    bits, sig = tls_cert(host, port)
    return (CONFIRMED if 0 < bits < 2048 else ABSENT), f"{bits}-bit key, signature {sig}"


def c_tls_sha1(host, port):
    bits, sig = tls_cert(host, port)
    weak = any(x in sig.lower() for x in ("sha1", "md5"))
    return (CONFIRMED if weak else ABSENT), f"{bits}-bit key, signature {sig}"


def c_tls_strong(host, port):
    bits, sig = tls_cert(host, port)
    ok = bits >= 2048 and not any(x in sig.lower() for x in ("sha1", "md5"))
    return (CONFIRMED if ok else ABSENT), f"{bits}-bit key, signature {sig} (control: expect strong)"


def c_proxy_open(host, port):
    s = tcp(host, port)
    s.sendall(b"GET http://example.invalid/ HTTP/1.0\r\nHost: example.invalid\r\n\r\n")
    r = s.recv(1024).decode("latin-1")
    s.close()
    first = r.split("\r\n", 1)[0]
    if not first.startswith("HTTP/"):
        raise Unreachable(f"not an HTTP proxy: {first!r}")
    if " 407 " in first or "407" in first.split(" ")[1:2]:
        return ABSENT, f"proxy asks for authentication: {first}"
    return CONFIRMED, f"proxy processed a request without credentials: {first}"


# ── IoT / AI emulator-backed ──────────────────────────────────────────────────

def rtsp_exchange(host, port, method):
    s = tcp(host, port)
    url = "*" if method == "OPTIONS" else f"rtsp://{host}:{port}/"
    s.sendall(f"{method} {url} RTSP/1.0\r\nCSeq: 1\r\n\r\n".encode())
    r = s.recv(2048).decode("latin-1")
    s.close()
    return r


def c_rtsp_options(host, port):
    r = rtsp_exchange(host, port, "OPTIONS")
    pub = next((ln.split(":", 1)[1].strip() for ln in r.split("\r\n")
                if ln.lower().startswith("public:")), "")
    return (CONFIRMED if r.startswith("RTSP/") and pub else ABSENT), f"Public: {pub}"


def c_rtsp_describe(host, port):
    r = rtsp_exchange(host, port, "DESCRIBE")
    first = r.split("\r\n", 1)[0]
    return (CONFIRMED if " 200 " in first else ABSENT), f"DESCRIBE -> {first}"


def c_adb_noauth(host, port):
    data = b"host::features=shell_v2,cmd\x00"
    hdr = struct.pack("<IIIIII", 0x4E584E43, 0x01000000, 256 * 1024, len(data),
                      sum(data) & 0xFFFFFFFF, 0x4E584E43 ^ 0xFFFFFFFF)
    s = tcp(host, port)
    s.sendall(hdr + data)
    r = recv_n(s, 24)
    s.close()
    cmd = struct.unpack("<I", r[:4])[0]
    if cmd == 0x4E584E43:
        return CONFIRMED, "CNXN returned with no AUTH step"
    return ABSENT, f"command 0x{cmd:08x} (AUTH means authenticated)"


def http_get(host, port, path):
    try:
        with urllib.request.urlopen(f"http://{host}:{port}{path}", timeout=8) as r:
            return r.status, r.read().decode("utf-8", "replace")
    except OSError as exc:
        raise Unreachable(str(exc))


def c_ollama(host, port):
    status, body = http_get(host, port, "/api/tags")
    return (CONFIRMED if status == 200 and '"models"' in body else ABSENT), f"/api/tags -> {status}"


def c_cwmp(host, port):
    status, body = http_get(host, port, "/")
    return (CONFIRMED if "cwmp" in body.lower() else ABSENT), f"GET / -> {status}"


def c_ssdp_igd(host, port):
    req = (b'M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\nMAN: "ssdp:discover"\r\n'
           b"MX: 3\r\nST: ssdp:all\r\n\r\n")
    r = udp_exchange(host, port, req)[0].decode("latin-1")
    loc = re.search(r"(?im)^location:\s*(\S+)", r)
    if not loc:
        return ABSENT, "SSDP reply has no LOCATION"
    with urllib.request.urlopen(loc.group(1), timeout=8) as resp:
        xml = resp.read().decode("utf-8", "replace")
    ok = "InternetGatewayDevice" in xml and "WANIPConnection" in xml
    return (CONFIRMED if ok else ABSENT), f"rootDesc at {loc.group(1)}: IGD+WANIPConnection={ok}"


def c_ntp_monlist(host, port):
    replies = udp_exchange(host, port, b"\x17\x00\x03\x2a" + b"\x00" * 4, timeout=4, extra_wait=1.0)
    first = replies[0]
    total = sum(len(x) for x in replies)
    if first[0] & 0x80 and (first[0] & 7) == 7:
        return CONFIRMED, f"monlist answered: {len(replies)} datagrams, {total} bytes for an 8-byte request (x{total // 8})"
    return ABSENT, f"no mode-7 response: {first[:8].hex()}"


def c_sip_options(host, port):
    req = (f"OPTIONS sip:probe@{host} SIP/2.0\r\nVia: SIP/2.0/UDP {host}:5060;branch=z9hG4bKlab1\r\n"
           f"Max-Forwards: 70\r\nTo: <sip:probe@{host}>\r\nFrom: <sip:lab@lab.invalid>;tag=lab1\r\n"
           "Call-ID: lab-probe-1\r\nCSeq: 1 OPTIONS\r\nContent-Length: 0\r\n\r\n").encode()
    r = udp_exchange(host, port, req)[0].decode("latin-1")
    first = r.split("\r\n", 1)[0]
    server = next((ln.split(":", 1)[1].strip() for ln in r.split("\r\n")
                   if ln.lower().startswith("server:")), "")
    return (CONFIRMED if first.startswith("SIP/2.0 200") else ABSENT), f"{first}; Server: {server}"


def c_nbns(host, port):
    q = (b"\x13\x37\x00\x00\x00\x01\x00\x00\x00\x00\x00\x00\x20"
         + b"CKAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA" + b"\x00\x00\x21\x00\x01")
    r = udp_exchange(host, port, q)[0]
    return (CONFIRMED if len(r) > 56 else ABSENT), f"NetBIOS node-status reply, {len(r)} bytes"


def c_mdns(host, port):
    q = (b"\x12\x34\x00\x00\x00\x01\x00\x00\x00\x00\x00\x00\x09_services\x07_dns-sd\x04_udp"
         b"\x05local\x00\x00\x0c\x00\x01")
    r = udp_exchange(host, port, q)[0]
    return (CONFIRMED if len(r) > 12 else ABSENT), f"mDNS answered unicast query, {len(r)} bytes"


# ── CLI-tool based ────────────────────────────────────────────────────────────

def c_dns_axfr(host, port):
    out = run(["dig", f"@{host}", "-p", str(port), "axfr", "lab.local", "+time=3", "+tries=1"])
    if "XFR size" in out:
        return CONFIRMED, "AXFR of lab.local completed"
    if "connection timed out" in out or "no servers could be reached" in out:
        raise Unreachable("DNS server unreachable")
    return ABSENT, "zone transfer refused"


def c_nfs_export(host, port):
    out = run(["showmount", "-e", host])
    if "/srv/lab/nfs" in out and "*" in out:
        return CONFIRMED, "export /srv/lab/nfs is open to *"
    if "RPC" in out or "Unable" in out or "timed out" in out:
        raise Unreachable(out.strip().splitlines()[0] if out.strip() else "no mountd")
    return ABSENT, out.strip()[:100]


def c_rsync_anon(host, port):
    out = run(["rsync", "--list-only", f"--port={port}", f"rsync://{host}/"])
    if "public" in out:
        return CONFIRMED, "anonymous module list includes 'public'"
    if "failed" in out or "refused" in out:
        raise Unreachable(out.strip()[:100])
    return ABSENT, out.strip()[:100]


def c_ldap_anon_search(host, port):
    out = run(["ldapsearch", "-x", "-H", f"ldap://{host}:{port}", "-b", "dc=lab,dc=local", "-LLL"])
    n = len(re.findall(r"(?m)^dn:", out))
    if n >= 2:
        return CONFIRMED, f"anonymous search returned {n} entries"
    if "Can't contact" in out:
        raise Unreachable("LDAP unreachable")
    return ABSENT, f"{n} entries returned"


def c_snmpv3_noauth(host, port):
    out = run(["snmpget", "-v3", "-l", "noAuthNoPriv", "-u", "labnoauth", "-t", "3", "-r", "1",
               f"{host}:{port}", "1.3.6.1.2.1.1.1.0"])
    if "STRING" in out or "sysDescr" in out:
        return CONFIRMED, "SNMPv3 noAuthNoPriv user answered"
    if "Timeout" in out:
        raise Unreachable("SNMP timeout")
    return ABSENT, out.strip()[:100]


def c_snmp_bulk(host, port):
    out = run(["snmpbulkwalk", "-v2c", "-c", "public", "-Cr50", "-t", "3", "-r", "1",
               f"{host}:{port}", "1.3.6.1.2.1"], timeout=30)
    lines = [ln for ln in out.splitlines() if "=" in ln]
    if len(lines) >= 20:
        return CONFIRMED, f"GETBULK returned {len(lines)} varbinds from one request"
    if "Timeout" in out:
        raise Unreachable("SNMP timeout")
    return ABSENT, f"only {len(lines)} varbinds"


CHECKS = {
    "ssh-weak": (2222, c_ssh_weak), "ssh-terrapin": (2223, c_ssh_terrapin),
    "vnc-none": (5900, c_vnc_none), "vnc-auth": (5901, c_vnc_auth),
    "ipmi-cipher0": (623, c_ipmi_cipher0), "redis-noauth": (6379, c_redis_noauth),
    "mqtt-anon": (1883, c_mqtt_anon), "mysql-cleartext": (3306, c_mysql_cleartext),
    "tftp-read": (69, c_tftp_read), "ftp-anon-write": (21, c_ftp_anon_write),
    "smtp-relay": (25, c_smtp_relay), "http-methods": (8080, c_http_methods),
    "tls-weakkey": (8444, c_tls_weakkey), "tls-sha1": (8445, c_tls_sha1),
    "tls-strong": (9443, c_tls_strong), "proxy-open": (3128, c_proxy_open),
    "rtsp-options": (554, c_rtsp_options), "rtsp-describe": (8554, c_rtsp_describe),
    "adb-noauth": (5555, c_adb_noauth), "ollama": (11434, c_ollama), "cwmp": (7547, c_cwmp),
    "ssdp-igd": (1900, c_ssdp_igd), "ntp-monlist": (123, c_ntp_monlist),
    "sip-options": (5060, c_sip_options), "nbns": (137, c_nbns), "mdns": (5353, c_mdns),
    "dns-axfr": (53, c_dns_axfr), "nfs-export": (2049, c_nfs_export),
    "rsync-anon": (873, c_rsync_anon), "ldap-anon-search": (389, c_ldap_anon_search),
    "snmpv3-noauth": (161, c_snmpv3_noauth), "snmp-bulk": (161, c_snmp_bulk),
}


def main(argv):
    if len(argv) >= 5 and argv[1] == "up":
        proto, host, port = argv[2], argv[3], int(argv[4])
        try:
            if proto == "tcp":
                tcp(host, port).close()
                print(f"{host}:{port}/tcp accepts connections")
            else:
                udp_exchange(host, port, b"\x00")
                print(f"{host}:{port}/udp answers")
            return CONFIRMED
        except Unreachable as exc:
            print(str(exc))
            return UNREACHABLE
    if len(argv) >= 4 and argv[1] == "check" and argv[2] in CHECKS:
        default_port, fn = CHECKS[argv[2]]
        host = argv[3]
        port = int(argv[4]) if len(argv) > 4 else default_port
        try:
            code, detail = fn(host, port)
        except Unreachable as exc:
            print(str(exc))
            return UNREACHABLE
        except (OSError, subprocess.SubprocessError, ValueError, IndexError, struct.error) as exc:
            print(f"probe error: {exc}")
            return UNREACHABLE
        print(detail)
        return code
    print("usage: lab_probe.py up tcp|udp HOST PORT | check NAME HOST [PORT]\nchecks: "
          + ", ".join(sorted(CHECKS)))
    return UNREACHABLE


if __name__ == "__main__":
    sys.exit(main(sys.argv))
VEDHA_PROBE_PY
  chmod 0755 "$LAB_DIR/lab_emulators.py" "$LAB_DIR/lab_probe.py"
}

usage() {
  local me
  me=$(basename "${BASH_SOURCE[0]}")
  awk 'NR>1 && /^#/ {sub(/^# ?/,""); print; next} NR>1 {exit}' "${BASH_SOURCE[0]}" \
    | sed "s#ubuntu-weak-lab\\.sh#$me#g"
  echo
  echo "Nothing was changed. To build the scenarios, run:"
  echo "  sudo ./$me up --allow-cidr <your scanner's network, e.g. 192.168.56.0/24> --i-understand-isolated-lab"
}

main() {
  local cmd="${1:-}"
  shift || true
  case "$cmd" in
    up)       parse_flags "$@"; cmd_up ;;
    verify)   parse_flags "$@"; cmd_verify ;;
    retry-failed) parse_flags "$@"; cmd_retry ;;
    down)     parse_flags "$@"; cmd_down ;;
    blind)    cmd_blind "$@" ;;
    unblind)  cmd_unblind "$@" ;;
    list)     cmd_list "$@" ;;
    report)   cat "$STATE_DIR/last-report.txt" 2>/dev/null || die "no report yet" ;;
    fw-apply) need_root; fw_apply ;;
    engine-selftest) cmd_engine_selftest ;;
    ""|-h|--help|help) usage ;;
    *) die "unknown command: $cmd (try --help)" ;;
  esac
}

main "$@"
